import{_ as p,a0 as l,w as r,s as o,ao as d,I as i,x as s,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"分步指南：安装和访问 Kubernetes 仪表板 | LCTT x X-CMD","titleTemplate":false,"description":"分步指南：安装和访问 Kubernetes 仪表板 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"分步指南：安装和访问 Kubernetes 仪表板 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"分步指南：安装和访问 Kubernetes 仪表板 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step","title":"分步指南：安装和访问 Kubernetes 仪表板","tag":"202308","desc":""},"relativePath":"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step.md","filePath":"[post].md"}'),h={name:"202308/20230717.3 ⭐️⭐️ How to Install and Access Kubernetes Dashboard Step-by-Step.md"};function b(u,e,c,g,k,m){const a=l("Link");return r(),o("div",null,[e[15]||(e[15]=d(`<h1 id="分步指南-安装和访问-kubernetes-仪表板" tabindex="-1">分步指南：安装和访问 Kubernetes 仪表板 <a class="header-anchor" href="#分步指南-安装和访问-kubernetes-仪表板" aria-label="Permalink to “分步指南：安装和访问 Kubernetes 仪表板”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/05/132420lppzypd5fzvhz1dy.jpg" alt=""></p><p>Kubernetes 是一个开源容器编排平台，已成为大规模管理容器化应用的首选解决方案。虽然 Kubernetes 提供了强大的命令行工具来管理集群，但有时可视化界面可以使监控和管理部署变得更加容易。Kubernetes 仪表板是一个基于 Web 的用户界面，可让你可视化 Kubernetes 集群并与之交互。</p><p>在这篇博文中，我们将逐步引导你完成安装和访问 Kubernetes Dashboard 的过程，使你能够简化 Kubernetes 管理任务。</p><p>先决条件：</p><p>在安装 Kubernetes Dashboard 之前，请确保你有一个正在运行的 Kubernetes 集群并具有必要的管理访问权限。</p><h3 id="安装-kubernetes-仪表板" tabindex="-1">安装 Kubernetes 仪表板 <a class="header-anchor" href="#安装-kubernetes-仪表板" aria-label="Permalink to “安装 Kubernetes 仪表板”">​</a></h3><p>为集群安装 Kubernetes 仪表板的简单方法是通过 Helm Chart。Kubernetes 仪表板现在依赖于 cert-manager 和 nginx-ingress-controller。幸运的是，可以使用 Helm Chart 自动安装这些依赖项。但是，如果你已经安装了这些组件，则可以在安装 Chart 时通过设置标志 <code>–set=nginx.enabled=false</code> 和 <code>–set=cert-manager.enabled=false</code> 来禁用它们的安装。</p><p>事不宜迟，让我们进入安装步骤。</p><h4 id="_1-安装-helm" tabindex="-1">1）安装 Helm <a class="header-anchor" href="#_1-安装-helm" aria-label="Permalink to “1）安装 Helm”">​</a></h4><p>使用终端或命令提示符访问集群的主节点。如果没有安装，请安装 helm。运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL -o get_helm.sh https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3</span></span>
<span class="line"><span>$ chmod 700 get_helm.sh</span></span>
<span class="line"><span>$ ./get_helm.sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Install-Helm-on-K8s-master-node.png" alt=""></p><h4 id="_2-添加-kubernetes-仪表板-helm-仓库" tabindex="-1">2）添加 Kubernetes 仪表板 Helm 仓库 <a class="header-anchor" href="#_2-添加-kubernetes-仪表板-helm-仓库" aria-label="Permalink to “2）添加 Kubernetes 仪表板 Helm 仓库”">​</a></h4><p>运行以下 <code>helm</code> 命令来添加仪表板仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo add kubernetes-dashboard https://kubernetes.github.io/dashboard/</span></span>
<span class="line"><span>$ helm repo list</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Helm-Repo-Kubernetes-Dashboard.png" alt=""></p><h4 id="_3-安装-kubernetes-仪表板" tabindex="-1">3）安装 Kubernetes 仪表板 <a class="header-anchor" href="#_3-安装-kubernetes-仪表板" aria-label="Permalink to “3）安装 Kubernetes 仪表板”">​</a></h4><p>要使用 <code>helm</code> 安装 Kubernetes 仪表板，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm upgrade --install kubernetes-dashboard kubernetes-dashboard/kubernetes-dashboard --create-namespace --namespace kubernetes-dashboard</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Installing-Kubernetes-Dashboard-Using-Helm-Command.png" alt=""></p><p>上面的输出确认仪表板已部署在 <code>Kubernetes-dashboard</code> 命名空间中。因此，要访问仪表板，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl -n kubernetes-dashboard port-forward svc/kubernetes-dashboard-nginx-controller 8443:443</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Port-Forwarding-Kubernetes-Dashboard-Kubectl-Command.png" alt=""></p><p>现在，打开运行上述命令的系统的 Web 浏览器，输入以下 URL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>https://localhost:8443</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Accept-Risk-SSL-Kubernetes-Dashboard.png" alt=""></p><p>点击“<ruby>接受风险并继续<rt>Accept the Risk and Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Token-For-Kubernetes-Dashboard-Login.png" alt=""></p><p>正如你在上面看到的，我们需要一个令牌才能登录。因此，让我们在下一步中生成所需的令牌。</p><h4 id="_4-为-kubernetes-仪表板生成令牌" tabindex="-1">4）为 Kubernetes 仪表板生成令牌 <a class="header-anchor" href="#_4-为-kubernetes-仪表板生成令牌" aria-label="Permalink to “4）为 Kubernetes 仪表板生成令牌”">​</a></h4><p>再打开一个到主节点的 SSH 会话，创建一个服务帐户并使用以下 yaml 文件分配所需的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi k8s-dashboard-account.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: ServiceAccount</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>  namespace: kube-system</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: rbac.authorization.k8s.io/v1</span></span>
<span class="line"><span>kind: ClusterRoleBinding</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>roleRef:</span></span>
<span class="line"><span>  apiGroup: rbac.authorization.k8s.io</span></span>
<span class="line"><span>  kind: ClusterRole</span></span>
<span class="line"><span>  name: cluster-admin</span></span>
<span class="line"><span>subjects:</span></span>
<span class="line"><span>- kind: ServiceAccount</span></span>
<span class="line"><span>  name: admin-user</span></span>
<span class="line"><span>  namespace: kube-system</span></span></code></pre></div><p>保存并退出文件。</p><p>接下来通过运行以下命令创建服务帐户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f k8s-dashboard-account.yaml</span></span>
<span class="line"><span>serviceaccount/admin-user created</span></span>
<span class="line"><span>clusterrolebinding.rbac.authorization.k8s.io/admin-user created</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>现在，为管理员用户生成令牌，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl -n kube-system  create token admin-user</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Generate-Token-K8s-Dashboard-kubectl-Command.png" alt=""></p><p>复制此令牌并返回浏览器，将其粘贴到“<ruby>输入令牌<rt>Enter token</rt></ruby>”字段中，如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Click-Signin-After-entering-token-kubernetes-dashboard.png" alt=""></p><p>点击“<ruby>登录<rt>Login</rt></ruby>”。</p><h4 id="_5-访问-kubernetes-仪表板" tabindex="-1">5) 访问 Kubernetes 仪表板 <a class="header-anchor" href="#_5-访问-kubernetes-仪表板" aria-label="Permalink to “5) 访问 Kubernetes 仪表板”">​</a></h4><p>当我们点击上面的“登录”时，我们将看到以下仪表板：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/07/Kubernetes-Dashboard-Overview-Ubuntu.png" alt=""></p><p>太好了，你现在已登录 Kubernetes 仪表板。以下是一些需要探索的关键特性和功能：</p><ul><li>集群概览：获取集群运行状况、资源利用率和运行 Pod 的概览。</li><li>工作负载：查看和管理你的部署、副本集、有状态集和守护程序集。</li><li>服务：监控和管理你的服务，包括负载均衡器和外部端点。</li><li>配置：探索你的配置映射、密钥和持久卷声明。</li><li>存储：管理持久卷和存储类。</li><li>命名空间：在命名空间之间切换以查看和管理不同项目或团队的资源。</li></ul><p>这就是这篇文章的全部内容，我希望你发现它有用且内容丰富。请在下面的评论部分发表你的疑问和反馈。</p><p><em>（题图：MJ/1bd0efb0-d4ee-4c8b-854a-49dbf38c5dd7）</em></p><hr>`,50)),i("p",null,[e[1]||(e[1]=s("via: ",-1)),n(a,{href:"https://www.linuxtechi.com/how-to-install-kubernetes-dashboard/"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.linuxtechi.com/how-to-install-kubernetes-dashboard/",-1)])]),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：",-1)),n(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...e[2]||(e[2]=[s("Pradeep Kumar",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),n(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...e[3]||(e[3]=[s("lkxed",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const y=p(h,[["render",b]]);export{x as __pageData,y as default};
